162	    func pushRegistry(_ registry: PKPushRegistry, didReceiveIncomingPushWith payload: PKPushPayload, for type: PKPushType, completion: @escaping () -> Void) {
163	        guard let roomID = payload.dictionaryPayload[ElementCallServiceNotificationKey.roomID.rawValue] as? String else {
164	            MXLog.error("Something went wrong, missing room identifier for incoming voip call: \(payload)")
165	            completion()
166	            return
167	        }
168	        
169	        guard let rtcNotificationID = payload.dictionaryPayload[ElementCallServiceNotificationKey.rtcNotifyEventID.rawValue] as? String else {
170	            MXLog.error("Something went wrong, missing rtc notification event identifier for incoming voip call: \(payload)")
171	            completion()
172	            return
173	        }
174	        
175	        guard ongoingCallID?.roomID != roomID else {
176	            MXLog.warning("Call already ongoing for room \(roomID), ignoring incoming push")
177	            completion()
178	            return
179	        }
180	        
181	        let isVoiceCall = payload.dictionaryPayload[ElementCallServiceNotificationKey.isVoiceCall.rawValue] as? Bool ?? false
182	        
183	        let callID = CallID(callKitID: UUID(), roomID: roomID, rtcNotificationID: rtcNotificationID, isVoiceCall: isVoiceCall)
184	        incomingCallID = callID
185	        
186	        guard let expirationDate = (payload.dictionaryPayload[ElementCallServiceNotificationKey.expirationDate.rawValue] as? Date) else {
187	            MXLog.error("Something went wrong, missing expiration timestamp for incoming voip call: \(payload)")
188	            completion()
189	            return
190	        }
191	        
192	        let nowDate = timeProvider.now()
193	        
194	        guard nowDate < expirationDate else {
195	            MXLog.warning("Call expired for room \(roomID), ignoring incoming push")
196	            completion()
197	            return
198	        }
199	        
200	        let ringDuration: Duration = .seconds(min(expirationDate.timeIntervalSince1970 - nowDate.timeIntervalSince1970, 90))
201	        
202	        let roomDisplayName = payload.dictionaryPayload[ElementCallServiceNotificationKey.roomDisplayName.rawValue] as? String
203	        
204	        let update = CXCallUpdate()
205	        update.hasVideo = !isVoiceCall
206	        update.localizedCallerName = roomDisplayName
207	        // https://stackoverflow.com/a/41230020/730924
208	        update.remoteHandle = .init(type: .generic, value: roomID)
209	        
210	        callProvider.reportNewIncomingCall(with: callID.callKitID, update: update) { [weak self] error in
211	            if let error {
212	                MXLog.error("Failed reporting new incoming call with error: \(error)")
213	            }
214	            
215	            self?.actionsSubject.send(.receivedIncomingCallRequest)
216	            
217	            completion()
218	        }
219	        
220	        endUnansweredCallTask = Task { [weak self] in
221	            try? await self?.timeProvider.clock.sleep(for: ringDuration)
222	            
223	            guard let self, !Task.isCancelled else {
224	                return
225	            }
226	            
227	            if let incomingCallID, incomingCallID.callKitID == callID.callKitID {
228	                callProvider.reportCall(with: incomingCallID.callKitID, endedAt: nil, reason: .unanswered)
229	            }
230	        }
231	    }
