247	    func provider(_ provider: CXProvider, perform action: CXAnswerCallAction) {
248	        guard let incomingCallID else {
249	            MXLog.error("Failed answering incoming call, missing incomingCallID")
250	            return
251	        }
252	        
253	        // Fixes broken videos on EC web when a CallKit session is established.
254	        //
255	        // Reporting an ongoing call through `reportNewIncomingCall` + `CXAnswerCallAction`
256	        // or `reportOutgoingCall:connectedAt:` will give exclusive access for media to the
257	        // ongoing process, which is different than the WKWebKit is running on, making EC
258	        // unable to aquire media streams.
259	        // Reporting the call as ended imediately after answering it works around that
260	        // as EC gets access to media again and EX builds the right UI in `setupCallSession`
261	        //
262	        // https://developer.apple.com/forums//thread/767949?answerId=812951022#812951022
263	        //
264	        // https://github.com/element-hq/element-x-ios/issues/3041
265	        // https://forums.developer.apple.com/forums/thread/685268
266	        // https://stackoverflow.com/questions/71483732/webrtc-running-from-wkwebview-avaudiosession-development-roadblock
267	        
268	        // First fullfill the action
269	        action.fulfill()
270	        
271	        // And delay ending the call so that the app has enough time
272	        // to get deeplinked into
273	        DispatchQueue.main.asyncAfter(deadline: .now() + 1.0) {
274	            // Then end the and call rely on `setupCallSession` to create a new one
275	            provider.reportCall(with: incomingCallID.callKitID, endedAt: nil, reason: .remoteEnded)
276	            
277	            self.actionsSubject.send(.startCall(roomID: incomingCallID.roomID, isVoiceCall: incomingCallID.isVoiceCall))
278	            self.endUnansweredCallTask?.cancel()
279	        }
280	    }
