292	    func provider(_ provider: CXProvider, perform action: CXEndCallAction) {
293	        #if targetEnvironment(simulator)
294	        // This gets called for no reason on simulators, where CallKit
295	        // isn't even supported, ignore it.
296	        #else
297	        if let ongoingCallID {
298	            actionsSubject.send(.endCall(roomID: ongoingCallID.roomID))
299	        }
300	        
301	        if let incomingCallID {
302	            Task {
303	                await sendDeclineCallEvent(incomingCallID)
304	            }
305	        }
306	        
307	        tearDownCallSession(sendEndCallAction: false)
308	        
309	        action.fulfill()
310	        #endif
311	    }
