328	    private func sendDeclineCallEvent(_ incomingCallID: CallID) async {
329	        guard let rtcNotificationID = incomingCallID.rtcNotificationID else {
330	            MXLog.info("No rtc notification event to decline.")
331	            return
332	        }
333	        
334	        guard let clientProxy else {
335	            MXLog.warning("A ClientProxy is needed to fetch the room.")
336	            return
337	        }
338	        
339	        guard case let .joined(roomProxy) = await clientProxy.roomForIdentifier(incomingCallID.roomID) else {
340	            MXLog.warning("Failed to fetch a joined room for the incoming call.")
341	            return
342	        }
343	        
344	        _ = await roomProxy.declineCall(notificationID: rtcNotificationID)
345	    }
346	    
347	    private func observeIncomingCall() async {
348	        incomingCallRoomInfoCancellable = nil
349	        
350	        guard let incomingCallID else {
351	            MXLog.info("No incoming call to observe for.")
352	            return
353	        }
354	        
355	        guard let clientProxy else {
356	            MXLog.warning("A ClientProxy is needed to fetch the room.")
357	            return
358	        }
359	        
360	        guard case let .joined(roomProxy) = await clientProxy.roomForIdentifier(incomingCallID.roomID) else {
361	            MXLog.warning("Failed to fetch a joined room for the incoming call.")
362	            return
363	        }
364	        
365	        roomProxy.subscribeToRoomInfoUpdates()
366	        
367	        incomingCallRoomInfoCancellable = roomProxy
368	            .infoPublisher
369	            .compactMap { ($0.hasRoomCall, $0.activeRoomCallParticipants) }
370	            .removeDuplicates { $0 == $1 }
371	            .drop { hasRoomCall, _ in
372	                // Filter all updates before hasRoomCall becomes `true`. Then we can correctly
373	                // detect its change to `false` to stop ringing when the caller hangs up.
374	                !hasRoomCall
375	            }
376	            .sink { [weak self] hasOngoingCall, activeRoomCallParticipants in
377	                guard let self else { return }
378	                
379	                let participants: [String] = activeRoomCallParticipants
380	                
381	                if !hasOngoingCall {
382	                    MXLog.info("Call cancelled by remote")
383	                    reportEndedCall(incomingCallID: incomingCallID, reason: .remoteEnded)
384	                } else if participants.contains(roomProxy.ownUserID) {
385	                    MXLog.info("Call answered elsewhere")
386	                    reportEndedCall(incomingCallID: incomingCallID, reason: .answeredElsewhere)
387	                }
388	            }
389	        
390	        guard let rtcNotificationID = incomingCallID.rtcNotificationID else {
391	            MXLog.warning("Decline: No RTC notification ID found for the incoming call.")
392	            return
393	        }
394	        
395	        MXLog.info("Observe decline events for notification \(rtcNotificationID)")
396	        
397	        let listener: CallDeclineListener = SDKListener { [weak self] senderID in
398	            guard let self else { return }
399	            
400	            MXLog.debug("Call declined event received from \(senderID)")
401	            
402	            if senderID == roomProxy.ownUserID {
403	                // Stop ringing!
404	                MXLog.debug("Call declined elsewhere")
405	                reportEndedCall(incomingCallID: incomingCallID, reason: .declinedElsewhere)
406	            }
407	        }
408	        
409	        guard case let .success(handle) = roomProxy.subscribeToCallDeclineEvents(rtcNotificationEventID: rtcNotificationID, listener: listener) else {
410	            MXLog.error("Unable to listen for decline events.")
411	            return
412	        }
413	        
414	        declineListenerHandle = handle
415	    }
416	    
417	    private func reportEndedCall(incomingCallID: CallID, reason: CXCallEndedReason) {
418	        declineListenerHandle?.cancel()
419	        declineListenerHandle = nil
420	        endUnansweredCallTask?.cancel()
421	        callProvider.reportCall(with: incomingCallID.callKitID, endedAt: nil, reason: reason)
422	    }
423	}
